bounded_host_request.command:
set -eu
target=''
count=0
while IFS= read -r name; do
  [ -n "$name" ] || continue
  if docker exec "$name" sh -c 'test -n "${VIDEOBOT_TELEGRAM_TOKEN_FILE:-}" && test -f "$VIDEOBOT_TELEGRAM_TOKEN_FILE" && command -v node >/dev/null' >/dev/null 2>&1; then
    target="$name"
    count=$((count+1))
  fi
done <<EOF
$(docker ps --format '{{.Names}}' | grep -Ei '(videobot|creator)' || true)
EOF
if [ "$count" -ne 1 ]; then
  echo CREATOR_CONTAINER_IDENTITY_NOT_UNIQUE
  exit 72
fi
docker exec -i "$target" node --input-type=module - <<'JS'
import {readFileSync} from 'node:fs';
import {setDefaultResultOrder} from 'node:dns';
import {setDefaultAutoSelectFamily} from 'node:net';
setDefaultResultOrder('ipv4first');
setDefaultAutoSelectFamily(false);
const tokenPath=process.env.VIDEOBOT_TELEGRAM_TOKEN_FILE;
const base=process.env.VIDEOBOT_LOCAL_API_URL||'https://api.telegram.org';
if(typeof tokenPath!=='string'||!tokenPath.startsWith('/run/secrets/')||
  !['https://api.telegram.org','http://telegram-bot-api:8081'].includes(base))
  throw Error('CREATOR_RUNTIME_SECRET_OR_ENDPOINT_INVALID');
const token=readFileSync(tokenPath,'utf8').trim();
if(!/^\d+:[A-Za-z0-9_-]{30,}$/.test(token))throw Error('CREATOR_TOKEN_FORMAT_INVALID');
async function call(method,params={}){
 const response=await fetch(base+'/bot'+token+'/'+method,{
  method:'POST',headers:{'content-type':'application/json'},
  body:JSON.stringify(params),signal:AbortSignal.timeout(25000),redirect:'error'
 });
 if(response.status!==200)throw Error('CREATOR_BOT_API_STATUS_ERROR');
 const result=await response.json();
 if(result?.ok!==true)throw Error('CREATOR_BOT_API_RESULT_ERROR');
 return result.result;
}
try{
 const me=await call('getMe');
 if(me?.is_bot!==true || String(me.username||'').toLowerCase()!=='createvdobot')
  throw Error('CREATOR_BOT_IDENTITY_MISMATCH');
 const languages=['','ja','en'];
 const scopes=['default','all_private_chats','all_group_chats','all_chat_administrators'];
 let cleared=0;
 for(const type of scopes){
  for(const language_code of languages){
   const p={scope:{type},language_code};
   await call('deleteMyCommands',p);
   const commands=await call('getMyCommands',p);
   if(!Array.isArray(commands)||commands.length!==0)
    throw Error('CREATOR_COMMAND_READBACK_NOT_EMPTY');
   cleared++;
  }
 }
 await call('setChatMenuButton',{menu_button:{type:'default'}});
 const menu=await call('getChatMenuButton');
 if(!menu||!['default','commands'].includes(menu.type))
  throw Error('CREATOR_MENU_RESET_NOT_VERIFIED');
 console.log('CREATOR_COMMAND_REGISTRATIONS_CLEARED='+cleared);
 console.log('CREATOR_MENU_SETTING='+menu.type);
 console.log('CREATOR_NO_COMMAND_READBACK=PASS');
}catch(e){console.error(String(e.message||'CREATOR_COMMAND_CLEANUP_FAILED').replace(/[^A-Z0-9_]/g,'_'));process.exitCode=1;}
JS
